import java.io.*
import java.util.*

const val MOD = 1_000_000_007L

fun power(a: Long, b: Long, m: Long): Long {
    var res = 1L
    var x = a % m
    var e = b
    while (e > 0) {
        if (e and 1L == 1L) res = res * x % m
        x = x * x % m
        e = e shr 1
    }
    return res
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    var n = st.nextToken().toLong()
    val k = st.nextToken().toInt()

    val primes = ArrayList<Long>()
    val exps = ArrayList<Int>()

    var d = 2L
    while (d * d <= n) {
        if (n % d == 0L) {
            var c = 0
            while (n % d == 0L) {
                n /= d
                c++
            }
            primes.add(d)
            exps.add(c)
        }
        d++
    }
    if (n > 1) {
        primes.add(n)
        exps.add(1)
    }

    var ans = 1L
    for (idx in primes.indices) {
        val p = primes[idx] % MOD
        val e = exps[idx]
        val inv = LongArray(e + 2)
        for (i in 1..e + 1) inv[i] = power(i.toLong(), MOD - 2, MOD)
        var dp = LongArray(e + 1)
        var cur = 1L
        for (j in 0..e) {
            dp[j] = cur
            cur = cur * p % MOD
        }
        var next = LongArray(e + 1)
        repeat(k) {
            var pref = 0L
            for (i in 0..e) {
                pref = (pref + dp[i]) % MOD
                next[i] = pref * inv[i + 1] % MOD
            }
            val tmp = dp
            dp = next
            next = tmp
        }
        ans = ans * dp[e] % MOD
    }
    println(ans)
}
